import { useEffect } from "react"
import { init, showPreferences, type InitOptions } from "./core"

export type CookieConsentProps = InitOptions

/**
 * Mount once, high in your tree. Initialises the consent manager on the client.
 * Renders nothing (the library manages its own DOM). StrictMode-safe.
 *
 *   import { CookieConsent } from "@premai/cookie-consent/react"
 *   import "@premai/cookie-consent/styles.css"
 *   <CookieConsent config={createConfig({ privacyPolicyUrl: "/privacy" })} />
 */
export function CookieConsent(props: CookieConsentProps): null {
    useEffect(() => {
        init(props)
        // Init runs once (guarded internally); options are read on first mount.
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [])
    return null
}

/** Returns a callback that re-opens the preferences modal. */
export function useManageCookies(): () => void {
    return showPreferences
}

export interface ManageCookiesButtonProps
    extends React.ButtonHTMLAttributes<HTMLButtonElement> {
    children?: React.ReactNode
}

/**
 * Unstyled button that re-opens the preferences modal. Pass `className`/`children`
 * to match your app; falls back to "Manage cookies".
 */
export function ManageCookiesButton({
    children = "Manage cookies",
    onClick,
    type = "button",
    ...rest
}: ManageCookiesButtonProps) {
    return (
        <button
            type={type}
            onClick={(e) => {
                onClick?.(e)
                if (!e.defaultPrevented) showPreferences()
            }}
            {...rest}
        >
            {children}
        </button>
    )
}

export {
    init,
    createConfig,
    showPreferences,
    show,
    acceptedCategory,
    validConsent,
    acceptCategory,
} from "./core"

export type {
    InitOptions,
    CreateConfigOptions,
    ConsentCategory,
    ConsentCopy,
    CookieConsentConfig,
} from "./core"
